import icontract
from typing import List


@icontract.ensure(lambda a, result: result == -1 or 0 <= result < len(a))
@icontract.ensure(lambda a, key, result: result == -1 or (
    0 <= result < len(a) and a[result] == key and all(a[i] != key for i in range(result))))
@icontract.ensure(lambda a, key, result: result != -1 or all(a[i] != key for i in range(len(a))))
def Find(a: List[int], key: int) -> int:
    index = 0
    while index < len(a):
        if a[index] == key:
            return index
        index += 1
    return -1
